// Writes src/components/land-outline.ts: the world's land as simplified
// polygon rings in degrees, for the Overview's resource-locations map, and
// the same rings as ../data/land_outline.json, which the CLI embeds for the
// map in the PDF and Word reports. One run writes both so they cannot drift
// (world-map.test.ts checks they agree).
//
// The source is Natural Earth's 1:110m land layer (public domain) as packaged
// by world-atlas (ISC), a dev dependency: nothing from the package ships, only
// this generated file does. Rings are simplified with Visvalingam weights,
// Antarctica is dropped (no Azure region is south of Chile), and coordinates
// are rounded to 0.01° — a map 400px wide cannot show finer detail. The
// projection is applied at render time in world-map.ts, so this file stays
// projection-agnostic.
//
//     node scripts/build-land-outline.mjs
import { createRequire } from "node:module";
import { writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import topojsonClient from "topojson-client";
import topojsonSimplify from "topojson-simplify";

const require = createRequire(import.meta.url);
const desktopDir = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const target = resolve(desktopDir, "src/components/land-outline.ts");
const dataTarget = resolve(desktopDir, "../data/land_outline.json");

const { feature } = topojsonClient;
const { presimplify, simplify, quantile } = topojsonSimplify;

const source = require("world-atlas/land-110m.json");
const weighted = presimplify(source);
// Keep roughly the top third of points by visual importance.
const simplified = simplify(weighted, quantile(weighted, 0.66));
const land = feature(simplified, simplified.objects.land);
// world-atlas stores land as a GeometryCollection, so this is a
// FeatureCollection of polygons and multipolygons.
const polygons = land.features.flatMap(({ geometry }) =>
  geometry.type === "MultiPolygon" ? geometry.coordinates : [geometry.coordinates],
);

// Natural Earth keeps two polygons (Chukotka with Alaska, and Fiji) across the
// antimeridian, so a naive projection draws each as a streak the width of the
// map. Unwrap each ring so it is continuous, then clip it at ±180° into the
// part that stays and the part that reappears on the far side.
function unwrap(ring) {
  const out = [ring[0]];
  let offset = 0;
  for (let index = 1; index < ring.length; index += 1) {
    let [lon, lat] = ring[index];
    lon += offset;
    const previous = out[index - 1][0];
    if (lon - previous > 180) {
      offset -= 360;
      lon -= 360;
    } else if (lon - previous < -180) {
      offset += 360;
      lon += 360;
    }
    out.push([lon, lat]);
  }
  return out;
}

function intersect(a, b, edge) {
  const t = (edge - a[0]) / (b[0] - a[0]);
  return [edge, a[1] + (b[1] - a[1]) * t];
}

// Sutherland–Hodgman against the vertical line lon = edge.
function clip(ring, edge, keepWest) {
  const inside = (point) => (keepWest ? point[0] <= edge : point[0] >= edge);
  const out = [];
  for (let index = 0; index < ring.length; index += 1) {
    const current = ring[index];
    const previous = ring[(index + ring.length - 1) % ring.length];
    if (inside(current)) {
      if (!inside(previous)) out.push(intersect(previous, current, edge));
      out.push(current);
    } else if (inside(previous)) {
      out.push(intersect(previous, current, edge));
    }
  }
  return out;
}

function splitAtAntimeridian(ring) {
  const continuous = unwrap(ring);
  const lons = continuous.map(([lon]) => lon);
  const min = Math.min(...lons);
  const max = Math.max(...lons);
  if (max > 180) {
    return [clip(continuous, 180, true), clip(continuous, 180, false).map(([lon, lat]) => [lon - 360, lat])];
  }
  if (min < -180) {
    return [clip(continuous, -180, false), clip(continuous, -180, true).map(([lon, lat]) => [lon + 360, lat])];
  }
  return [continuous];
}

const rings = [];
let split = 0;
for (const polygon of polygons) {
  for (const source of polygon) {
    if (source.length < 4) continue;
    if (Math.max(...source.map(([, lat]) => lat)) < -60) continue; // Antarctica
    const parts = splitAtAntimeridian(source);
    if (parts.length > 1) split += 1;
    for (const ring of parts) {
    if (ring.length < 4) continue;
    const flat = [];
    let last = "";
    for (const [lon, lat] of ring) {
      const x = Math.round(lon * 100) / 100;
      const y = Math.round(lat * 100) / 100;
      const key = `${x},${y}`;
      if (key === last) continue;
      last = key;
      flat.push(x, y);
    }
    if (flat.length >= 8) rings.push(flat);
    }
  }
}
console.log(`split ${split} rings at the antimeridian`);

const points = rings.reduce((sum, ring) => sum + ring.length / 2, 0);
const body = rings.map((ring) => `  [${ring.join(", ")}],`).join("\n");
writeFileSync(
  target,
  `// @generated by desktop/scripts/build-land-outline.mjs — do not edit.
// Natural Earth 1:110m land (public domain) via world-atlas, simplified to
// ${points} points in ${rings.length} rings; [lon, lat, lon, lat, …] per ring.
export const LAND_RINGS: ReadonlyArray<ReadonlyArray<number>> = [
${body}
];
`,
);
writeFileSync(dataTarget, `[\n${rings.map((ring) => `[${ring.join(",")}]`).join(",\n")}\n]\n`);
console.log(`wrote ${target} and ${dataTarget}: ${rings.length} rings, ${points} points`);
